import{checkScore,MUSIC_KEYS}from'./music-compose.js';
export function mountPianoRoll({root,score,part,page=0,barsPerPage=4,quantum=6,tool='select',range,colour=()=>null,onSelect,onChange,onRange,error=()=>{}}){
 const track=score.tracks[part],pageTicks=barsPerPage*96,pages=Math.ceil(score.length/pageTicks);page=Math.max(0,Math.min(pages-1,page));const start=page*pageTicks,end=Math.min(score.length,start+pageTicks),row=26,left=58,scale=Math.max(1.5,((root.clientWidth||700)-left)/pageTicks),width=left+pageTicks*scale,visible=track.notes.map((n,index)=>({...n,index})).filter(n=>n.tick<end&&n.tick+n.duration>start),all=track.notes,low=Math.max(0,Math.min(48,...all.map(n=>n.key))-2),high=Math.min(127,Math.max(72,...all.map(n=>n.key))+2),height=(high-low+1)*row,old={top:root.scrollTop,left:root.scrollLeft};
 const name=k=>MUSIC_KEYS[k%12]+(Math.floor(k/12)-1),x=t=>left+(t-start)*scale,y=k=>(high-k)*row,black=k=>[1,3,6,8,10].includes(k%12),inside=range&&range.end>start&&range.start<end;
 root.style.touchAction=tool==='scroll'?'auto':'none';root.innerHTML=`<div class="roll-timebar" style="width:${width}px"><svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="28" viewBox="0 0 ${width} 28" aria-hidden="true"><rect width="${width}" height="28" fill="#253b35"/>${Array.from({length:barsPerPage*4+1},(_,i)=>`<text x="${x(start+i*24)+3}" y="19" font-size="${i%4?10:13}" fill="${i%4?'#b1c3b9':'#fff6dc'}">${i%4?i%4+1:Math.floor((start+i*24)/96)+1}</text>`).join('')}</svg></div><svg data-note-grid="true" xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" role="application" aria-label="Note editor. Select riff and drag from A to B. Draw adds notes; Move edits notes; Scroll pans.">${Array.from({length:high-low+1},(_,i)=>{const k=high-i;return`<rect x="0" y="${i*row}" width="${width}" height="${row}" fill="${black(k)?'#dfe6d8':'#f3f6ed'}"/><rect x="0" y="${i*row}" width="${left}" height="${row}" fill="${black(k)?'#334632':'#fffdf2'}"/><text x="6" y="${i*row+18}" font-size="13" fill="${black(k)?'#fffdf2':'#243626'}">${name(k)}</text><path d="M0 ${i*row}H${width}" stroke="#c1ccbb"/>`;}).join('')}${Array.from({length:Math.ceil((end-start)/quantum)+1},(_,i)=>{const t=start+i*quantum;return`<path d="M${x(t)} 0V${height}" stroke="${t%96===0?'#556e4a':t%24===0?'#9cac91':'#d1dac8'}" stroke-width="${t%96===0?2:1}"/>`;}).join('')}${inside?`<rect pointer-events="none" x="${x(Math.max(start,range.start))}" y="0" width="${(Math.min(end,range.end)-Math.max(start,range.start))*scale}" height="${height}" fill="#d3a839" opacity=".22"/>`:''}${visible.map(n=>`<g data-roll-note="${n.index}"><rect data-note-body="${n.index}" x="${Math.max(left,x(n.tick))}" y="${y(n.key)+2}" width="${Math.max(5,(Math.min(n.tick+n.duration,end)-Math.max(n.tick,start))*scale)}" height="22" rx="4" fill="${colour(n.index)||'#507846'}"/><rect data-note-resize="${n.index}" x="${Math.max(left,x(Math.min(end,n.tick+n.duration))-Math.min(18,n.duration*scale*.4))}" y="${y(n.key)+2}" width="${Math.max(4,Math.min(18,n.duration*scale*.4))}" height="22" rx="3" fill="#243f26"/><title>${name(n.key)}, bar ${Math.floor(n.tick/96)+1}, ${n.duration} ticks</title></g>`).join('')}${range?['start','end'].filter(k=>range[k]>=start&&range[k]<=end).map(k=>`<g data-range-handle="${k}" style="pointer-events:${tool==='range'?'all':'none'}"><rect x="${x(range[k])-9}" y="0" width="18" height="${height}" fill="#b17b19" opacity=".12"/><path d="M${x(range[k])} 0V${height}" stroke="#a16e12" stroke-width="3"/><text x="${x(range[k])+4}" y="18" font-size="16" fill="#6f4904">${k==='start'?'A':'B'}</text></g>`).join(''):''}<rect id="rollGesture" pointer-events="none" fill="#b2812c" opacity=".35" hidden/></svg>`;
 for(const svg of root.querySelectorAll('svg')){svg.style.setProperty('width',width+'px','important');svg.style.setProperty('min-width',width+'px','important');svg.style.setProperty('height',(svg.hasAttribute('data-note-grid')?height:28)+'px','important');}
 root.scrollTop=root.dataset.rollPart===String(part)?old.top:Math.max(0,y(visible.length?Math.round(visible.reduce((a,n)=>a+n.key,0)/visible.length):60)-100);root.scrollLeft=old.left;root.dataset.rollPart=String(part);
 const svg=root.querySelector('[data-note-grid]'),ghost=svg.querySelector('#rollGesture');let gesture=null;
 const position=e=>{const box=svg.getBoundingClientRect(),px=(e.clientX-box.left)*width/(box.width||width),py=(e.clientY-box.top)*height/(box.height||height);return{tick:Math.max(start,Math.min(end,start+Math.round((px-left)/scale/quantum)*quantum)),key:Math.max(low,Math.min(high,high-Math.floor(py/row))),px,py};};
 const showRange=r=>{ghost.removeAttribute('hidden');ghost.setAttribute('x',x(Math.max(start,r.start)));ghost.setAttribute('y',0);ghost.setAttribute('width',(Math.min(end,r.end)-Math.max(start,r.start))*scale);ghost.setAttribute('height',height);onRange?.(r);};
 const show=n=>{ghost.removeAttribute('hidden');for(const[k,v]of Object.entries({x:x(n.tick),y:y(n.key)+2,width:Math.max(5,n.duration*scale),height:22}))ghost.setAttribute(k,v);};
 svg.onpointerdown=e=>{if(tool==='scroll'||e.button>0||e.isPrimary===false)return;const p=position(e);if(p.px<left)return;e.preventDefault();svg.setPointerCapture?.(e.pointerId);const target=e.target.closest('[data-roll-note]'),index=target?+target.dataset.rollNote:null,n=index===null?null:track.notes[index];if(tool==='erase'){if(n)commit(track.notes.filter((_,i)=>i!==index));return;}if(tool==='range'){const handle=e.target.closest('[data-range-handle]')?.dataset.rangeHandle;gesture={id:e.pointerId,type:'range',origin:Math.min(score.length-quantum,p.tick),handle,original:range?{...range}:null};if(!handle)showRange({start:gesture.origin,end:Math.min(score.length,gesture.origin+quantum)});return;}if(!n&&tool!=='draw')return;gesture={id:e.pointerId,index,origin:p,note:n?{...n}:{tick:Math.min(score.length-1,p.tick),key:p.key,duration:Math.min(quantum,score.length-p.tick)||1,velocity:90},type:e.target.hasAttribute('data-note-resize')?'resize':n?'move':'draw'};show(gesture.note);};
 svg.onpointermove=e=>{if(!gesture||gesture.id!==e.pointerId)return;const p=position(e),g=gesture;if(g.type==='range'){if(g.handle){const r={...g.original};r[g.handle]=g.handle==='start'?Math.min(r.end-quantum,p.tick):Math.max(r.start+quantum,p.tick);showRange(r);}else showRange({start:Math.min(p.tick,g.origin),end:Math.min(score.length,Math.max(p.tick,g.origin)+quantum)});return;}let n={...g.note};if(g.type==='move'){n.tick=Math.max(0,Math.min(score.length-n.duration,n.tick+p.tick-g.origin.tick));n.key=p.key;}else n.duration=Math.max(quantum,Math.min(score.length-n.tick,p.tick-n.tick+quantum));g.next=n;show(n);};
 svg.onpointerup=e=>{if(!gesture||gesture.id!==e.pointerId)return;const g=gesture;gesture=null;if(g.type==='range')return;ghost.setAttribute('hidden','');if(g.index!==null&&!g.next){onSelect?.(g.index);return;}const notes=track.notes.map(n=>({...n})),n=g.next||g.note;if(g.index===null)notes.push(n);else notes[g.index]=n;commit(notes);};svg.onpointercancel=()=>{gesture=null;ghost.setAttribute('hidden','');};
 function commit(notes){try{checkScore({...score,tracks:score.tracks.map((t,i)=>i===part?{...t,notes}:t)},{arranging:true});onChange?.(notes);}catch(e){error(e);}}
 return{start,end,page,barsPerPage};
}
